insert into public.game_programs(owner_id,purchase_threshold,earning_enabled) select owner_id,500,false from public.store_settings on conflict(owner_id) do nothing;
insert into public.crm_games(owner_id,game_key,engine,name,difficulty,enabled,prizes) select s.owner_id,'paw-wheel','wheel','วงล้ออุ้งเท้า','easy',false,(select jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'title',v.points::text||' แต้ม','kind','points','image','','color',v.color,'points',v.points,'weight',v.weight,'stock',null,'active',true,'discountType','percent','discountValue',5,'minSpend',0,'maxDiscount',null,'expiryMode','hours','expiryHours',168,'expiresAt',null) order by v.points) from (values(2,40,'#f8d2b0'),(5,35,'#d4c1f2'),(10,25,'#bfe8d4')) as v(points,weight,color)) from public.store_settings s on conflict(owner_id,game_key) do nothing;
